252→            println!("Spiced Runtime Metrics:");
253→            println!("{}", vec!["="; 30].join(""));
254→
255→            // Display and optionally emit key metrics
256→            // Note: Prometheus exporter appends _total to counter metrics
257→            if let Some(query_count) = metrics.get_counter_value("query_executions_total") {
258→                println!("Total Queries Executed: {query_count}");
259→
260→                if emit_to_telemetry {
261→                    crate::metrics::SPICED_QUERY_COUNT.record(query_count, attributes);
262→                }
263→            }
264→
265→            if let Some(cache_hits) = metrics.get_counter_value("results_cache_hits_total")
266→                && let Some(cache_requests) =
267→                    metrics.get_counter_value("results_cache_requests_total")
268→                && cache_requests > 0.0
269→            {
270→                let hit_rate = cache_hits / cache_requests;
271→                println!("Cache Hit Rate: {:.2}%", hit_rate * 100.0);
272→
273→                if emit_to_telemetry {
274→                    crate::metrics::SPICED_CACHE_HIT_RATE.record(hit_rate, attributes);
275→                }
276→            }
277→
278→            if let Some(active_conns) = metrics.get_gauge_max("query_active_count") {
279→                println!("Peak Active Connections: {active_conns}");
280→
281→                if emit_to_telemetry {
282→                    crate::metrics::SPICED_ACTIVE_CONNECTIONS.record(active_conns, attributes);
283→                }
284→            }
285→
286→            println!("{}", vec!["="; 30].join(""));
287→            Some(metrics)
288→        }
289→        Err(e) => {
290→            println!("Warning: Failed to collect spiced metrics: {e}");
291→            None
292→        }
293→    }
294→}
